1	// `@goodfetch/collie` (ADRs 0090, 0095): Collie's TypeScript SDK and its `goodfetch-collie` bin. It
2	// re-exports the Collie client package, whose values (Run, Session, Page, errors) a Foxhound handler
3	// gets too, and adds the connection, which finds Collie's executable through its own platform
4	// packages and reads only `GOODFETCH_COLLIE_ENGINE_PATH` (ADR 0090).
5	export * from "@goodfetch/collie-client";
6	
7	import type {
8	  CallOptions,
9	  ConnectOptions,
10	  Connection,
11	  EngineInfo,
12	  ExplainedSetting,
13	  Identities,
14	  JSONObject,
15	  JSONValue,
16	  Run,
17	  RunView,
18	  SettingKey,
19	  StartOptions,
20	} from "@goodfetch/collie-client";
21	
22	/**
23	 * A connection to an engine, Collie's or Foxhound's (ADR 0095): the entry point (ADR 0078). Each one
24	 * is independent, and many may be open in one process. A Collie connection announces Collie in
25	 * `hello`, so a Foxhound engine accepts it too.
26	 */
27	export declare class Collie implements Connection {
28	  private constructor();
29	  /** Starts or finds the engine and completes `hello` before returning. */
30	  static connect(options?: ConnectOptions): Promise<Collie>;
31	  engine(): EngineInfo;
32	  /** The install's Saved identities (ADR 0092). */
33	  readonly identities: Identities;
34	  start(options?: StartOptions): Promise<Run>;
35	  openRun(id: string, options?: CallOptions): Promise<RunView>;
36	  /** Cancels in-flight calls, closes every Run it opened and ends every borrow; stops an Attached engine, only disconnects from a Daemon. */
37	  close(options?: CallOptions): Promise<void>;
38	  [Symbol.asyncDispose](): Promise<void>;
39	  explainSettings(keys?: readonly SettingKey[], options?: CallOptions): Promise<readonly ExplainedSetting[]>;
40	  /** The raw catalog call (ADR 0099): `params` names every value itself. */
41	  call(operation: string, params?: JSONObject, options?: CallOptions): Promise<JSONValue>;
42	}

1	// `@goodfetch/collie-client` (ADR 0095): the Collie client package, with no executable. It holds the
2	// hand-written runtime, the generated layer of Collie's catalog and every value a Collie connection
3	// hands out (Runs, Sessions, Pages, Locators, results, errors, settings types). Programs import their
4	// Product's package, `@goodfetch/collie` or `@goodfetch/foxhound`, which re-exports this one; only a
5	// library meant to serve both Products imports it, as a peer dependency.
6	export * from "./agent.js";
7	export * from "./ai.js";
8	export * from "./catalog.js";
9	export * from "./concurrency.js";
10	export * from "./data.js";
11	export * from "./effects.js";
12	export * from "./lending.js";
13	export * from "./lifecycle.js";
