31	// Locators.
32	
33	/** ARIA roles, as `getByRole` takes them. A sample: the SDK lists every ARIA role. */
34	export type AriaRole =
35	  | "alert"
36	  | "button"
37	  | "checkbox"
38	  | "combobox"
39	  | "dialog"
40	  | "heading"
41	  | "link"
42	  | "listbox"
43	  | "listitem"
44	  | "menuitem"
45	  | "option"
46	  | "radio"
47	  | "row"
48	  | "searchbox"
49	  | "tab"
50	  | "table"
51	  | "textbox";
52	
53	/**
54	 * Text to match. A string matches as a case-insensitive substring after whitespace is normalized,
55	 * as in Playwright, or exactly with `exact: true`. A `RegExp` runs in the engine, in the Rust `regex`
56	 * syntax (ADR 0081).
57	 */
58	export type TextMatch = string | RegExp;
59	
60	export interface TextOptions {
61	  readonly exact?: boolean;
62	}
63	
64	export interface GetByRoleOptions extends TextOptions {
65	  /** The accessible name. */
66	  readonly name?: TextMatch;
67	  readonly checked?: boolean;
68	  readonly disabled?: boolean;
69	  readonly expanded?: boolean;
70	  readonly includeHidden?: boolean;
71	  readonly level?: number;
72	  readonly pressed?: boolean;
73	  readonly selected?: boolean;
74	}
75	
76	/** Declarative filters, resolved by the engine: no host callback ever runs in the page. */
77	export interface FilterOptions {
78	  readonly hasText?: TextMatch;
79	  readonly hasNotText?: TextMatch;
80	  readonly has?: Locator;
81	  readonly hasNot?: Locator;
82	  readonly visible?: boolean;
83	}
84	
85	/** The locator constructors that pages, frame locators and locators share. None does I/O. */
86	export interface Locates {
87	  /**
88	   * CSS, or XPath when the string starts with `//`, `..` or `xpath=`. CSS pierces open shadow
89	   * roots; XPath does not. Playwright's other selector engines (`text=`, `role=`, `internal:`), `>>`
90	   * chains and its CSS extensions (`:has-text()`, `:text()`, `:visible`, `:nth-match()`) fail with
91	   * `SelectorInvalidError`, whose fix names the method that replaces them.
92	   */
93	  locator(selector: string, options?: FilterOptions): Locator;
94	  getByRole(role: AriaRole, options?: GetByRoleOptions): Locator;
95	  getByText(text: TextMatch, options?: TextOptions): Locator;
96	  getByLabel(text: TextMatch, options?: TextOptions): Locator;
97	  getByPlaceholder(text: TextMatch, options?: TextOptions): Locator;
98	  getByAltText(text: TextMatch, options?: TextOptions): Locator;
99	  getByTitle(text: TextMatch, options?: TextOptions): Locator;
100	  /** Matches the attribute named by the setting `locator.test_id_attribute`, `data-testid` by default. */
101	  getByTestId(testId: TextMatch): Locator;
102	  /**
103	   * Enters an iframe matched by `selector`, same-origin or cross-origin alike. Without a selector,
104	   * the search starts in every frame of the page; the rest of the locator resolves inside one frame.
105	   */
106	  frameLocator(selector?: string): FrameLocator;
107	}
108	
109	/** An iframe's content, resolved again at each use. Strict: its `iframe` must be unique. */
110	export interface FrameLocator extends Locates {
111	  /** The `iframe` element itself. */
112	  owner(): Locator;
113	}
114	
115	export type Modifier = "Alt" | "Control" | "ControlOrMeta" | "Meta" | "Shift";
116	
117	export interface Position {
118	  readonly x: number;
119	  readonly y: number;
120	}
121	
122	export interface BoundingBox {
123	  readonly x: number;
124	  readonly y: number;
125	  readonly width: number;
126	  readonly height: number;
127	}
128	
129	/** Options of a guarded action. Its timeout is the action phase's (ADR 0080). */
130	export interface ActionOptions extends CallOptions {
131	  /**
132	   * Skips the guard's actionability checks and its replay, keeps uniqueness, and marks the action
133	   * unguarded in Provenance: the setting `action.force` for this call alone (ADR 0023).
134	   */
135	  readonly force?: boolean;
136	}
137	
138	export interface PointerOptions extends ActionOptions {
139	  readonly modifiers?: readonly Modifier[];
140	  /** Relative to the element's top-left corner; its visible centre by default. */
141	  readonly position?: Position;
142	}
143	
144	export interface ClickOptions extends PointerOptions {
145	  readonly button?: "left" | "right" | "middle";
146	  readonly clickCount?: number;
147	  /** Milliseconds between pressing and releasing. */
148	  readonly delay?: number;
149	}
150	
151	export interface KeyOptions extends ActionOptions {
152	  /** Milliseconds between key presses. */
153	  readonly delay?: number;
154	}
155	
156	/** A file held in memory. */
157	export interface FilePayload {
158	  readonly name: string;
159	  readonly mimeType: string;
160	  readonly buffer: Uint8Array;
161	}
162	
163	/**
164	 * Files to upload: paths on the program's machine, which the SDK reads and streams over the
165	 * connection, or files in memory. An empty list clears the input.
166	 */
167	export type InputFiles = string | FilePayload | readonly string[] | readonly FilePayload[];
168	
169	export type SelectOptionValue =
170	  | string
171	  | { readonly value: string }
172	  | { readonly label: string }
173	  | { readonly index: number };
174	
175	/** A page function sees only its argument; the page runs it in its main world unless asked otherwise. */
176	export interface EvaluateOptions extends CallOptions {
177	  /**
178	   * `main`, the default, sees the page's own globals and is marked in Provenance (ADR 0019);
179	   * `isolated` runs where the page can neither see nor hook it.
180	   */
181	  readonly world?: "main" | "isolated";
182	}
183	
184	/** What a page function may return: JSON, or nothing. */
185	export type PageResult = JSONValue | undefined | void;
186	
187	/**
188	 * JavaScript run in the page: a function, whose source is sent and which sees only its argument,
189	 * or source text, a function if it parses as one and otherwise an expression. Values cross as JSON
190	 * both ways; anything else throws `PageValueInvalidError` naming its path.
191	 */
192	export type PageFunction<Arg extends JSONValue, R extends PageResult> = string | ((arg: Arg) => R | Promise<R>);
193	/** A page function given the locator's element first. */
194	export type ElementFunction<Arg extends JSONValue, R extends PageResult> =
195	  | string
196	  | ((element: Element, arg: Arg) => R | Promise<R>);
197	/** A page function given every matching element first. */
198	export type ElementsFunction<Arg extends JSONValue, R extends PageResult> =
199	  | string
200	  | ((elements: Element[], arg: Arg) => R | Promise<R>);
201	
202	export interface ScreenshotOptions extends CallOptions {
203	  readonly type?: "png" | "jpeg";
204	  readonly quality?: number;
205	  readonly omitBackground?: boolean;
206	  readonly animations?: "allow" | "disabled";
207	  readonly caret?: "hide" | "initial";
208	  readonly scale?: "css" | "device";
209	  /** Covered with a box; Secrets are masked by the engine anyway (ADR 0014). */
210	  readonly mask?: readonly Locator[];
211	  readonly maskColor?: string;
212	  /** Also written to this path on the program's machine. */
213	  readonly path?: string;
214	}
215	
216	export interface PageScreenshotOptions extends ScreenshotOptions {
217	  readonly fullPage?: boolean;
218	  readonly clip?: BoundingBox;
219	}
220	
221	/**
222	 * A lazy description of elements, built without I/O and resolved again at each use. A cheap value:
223	 * composing one never touches the page.
224	 */
225	export interface Locator extends Locates, AIVerbs, AriaSnapshots, RawCall {
226	  filter(options: FilterOptions): Locator;
227	  and(locator: Locator): Locator;
228	  or(locator: Locator): Locator;
229	  /** Opts out of strictness: the first match. */
230	  first(): Locator;
231	  last(): Locator;
232	  nth(index: number): Locator;
233	  /** The content of the `iframe` this locator matches. */
234	  contentFrame(): FrameLocator;
235	  /** One locator per element matching now. Answers at once, with no timeout. */
236	  all(): Promise<Locator[]>;
237	
238	  // Gestures: guarded, and run one at a time on the page.
239	  /** Waits until the target is unique, visible, stable, enabled and receiving the click, then clicks; a click that lands elsewhere is cancelled and replayed. */
240	  click(options?: ClickOptions): Promise<void>;
241	  dblclick(options?: ClickOptions): Promise<void>;
242	  tap(options?: PointerOptions): Promise<void>;
243	  hover(options?: PointerOptions): Promise<void>;
244	  check(options?: PointerOptions): Promise<void>;
245	  uncheck(options?: PointerOptions): Promise<void>;
246	  setChecked(checked: boolean, options?: PointerOptions): Promise<void>;
247	  dragTo(target: Locator, options?: ActionOptions & { readonly sourcePosition?: Position; readonly targetPosition?: Position }): Promise<void>;
248	  /**
249	   * Clears the field and inserts the text as typed text arrives, so controlled inputs see it. On a
250	   * `<label>`, acts on its control. A target that cannot hold text throws `TargetUnsupportedError` at
251	   * once; a read-only one is waited for.
252	   * A Secret placeholder is typed by the engine, checked against the domain of the field's frame
253	   * (ADR 0092); reads of the field then show `%name%`.
254	   */
255	  fill(value: string | SecretPlaceholder, options?: ActionOptions): Promise<void>;
256	  clear(options?: ActionOptions): Promise<void>;
257	  /** A key or a combination, such as `Enter` or `ControlOrMeta+A`. */
258	  press(key: string, options?: KeyOptions): Promise<void>;
259	  /** Types key by key, for fields that react to each keystroke; a Secret placeholder as `fill` types it. */
260	  pressSequentially(text: string | SecretPlaceholder, options?: KeyOptions): Promise<void>;
261	  /** On a `<select>`, or the control a `<label>` points to. Returns the values selected. */
262	  selectOption(values: SelectOptionValue | readonly SelectOptionValue[], options?: ActionOptions): Promise<string[]>;
263	  selectText(options?: ActionOptions): Promise<void>;
264	  /** On a file input, or the one a `<label>` points to. */
265	  setInputFiles(files: InputFiles, options?: ActionOptions): Promise<void>;
266	  focus(options?: CallOptions): Promise<void>;
267	  blur(options?: CallOptions): Promise<void>;
268	  scrollIntoViewIfNeeded(options?: CallOptions): Promise<void>;
269	
270	  // Reads: one round trip each, whatever the number of matches.
271	  /** Waits for one element, as an action does, under the action timeout. */
272	  textContent(options?: CallOptions): Promise<string>;
273	  innerText(options?: CallOptions): Promise<string>;
274	  innerHTML(options?: CallOptions): Promise<string>;
275	  inputValue(options?: CallOptions): Promise<string>;
276	  /** `null` when the attribute is absent: an answer, not a failure. */
277	  getAttribute(name: string, options?: CallOptions): Promise<string | null>;
278	  /** `null` when the element is not visible. */
279	  boundingBox(options?: CallOptions): Promise<BoundingBox | null>;
280	  isEnabled(options?: CallOptions): Promise<boolean>;
281	  isDisabled(options?: CallOptions): Promise<boolean>;
282	  isChecked(options?: CallOptions): Promise<boolean>;
283	  isEditable(options?: CallOptions): Promise<boolean>;
284	  /** Answers at once, with no timeout: no match is not visible; two matches throw `TargetNotUniqueError`. */
285	  isVisible(): Promise<boolean>;
286	  isHidden(): Promise<boolean>;
287	  /** Answers at once. To wait for a count, `waitForCount`. */
288	  count(): Promise<number>;
289	  allTextContents(): Promise<string[]>;
290	  allInnerTexts(): Promise<string[]>;
291	  screenshot(options?: ScreenshotOptions): Promise<Uint8Array>;
292	
293	  // Page functions.
294	  evaluate<R extends PageResult = JSONValue, Arg extends JSONValue = JSONValue>(
295	    pageFunction: ElementFunction<Arg, R>,
296	    arg?: Arg,
297	    options?: EvaluateOptions,
298	  ): Promise<R>;
